from pathlib import Path

scenario = Path("scenarios/missions/d66_lvl10-16_mission_01_blacksun.md")
s = scenario.read_text(encoding="utf-8")

old_05 = """- 同一マスが出た場合
  既に解決済みの番号が出た場合、その番号は使用せず、番号を1つずつ増やして、未使用の番号に到達するまで進める。
  例：25番と26番をすでに解決している状態で　再び 25 が出た場合
    25 → 使用済み
    26 → 使用済み
    31 → 未使用
  この場合、31番のマップイベントを解決する。
"""
new_05 = """- 同一マスが出た場合
  既に解決済みの番号が出た場合、その番号は使用せず、番号を1つずつ増やして、未使用の番号に到達するまで進める。
  一本道モードの6～10枚目では、06章の最終イベント出現判定を先に行い、最終イベントが出現しなかった場合にのみ、この未使用番号への繰り上げ処理を行う。繰り上げ後の番号では最終イベント出現判定をやり直さない。
  例：25番と26番をすでに解決している状態で　再び 25 が出た場合
    25 → 使用済み
    26 → 使用済み
    31 → 未使用
  この場合、31番のマップイベントを解決する。
"""
if s.count(old_05) != 1:
    raise SystemExit(f"section05 marker count must be 1, got {s.count(old_05)}")
s = s.replace(old_05, new_05, 1)

old_steps = """1. 次の区域へ進出する。
2. 11枚目なら d66 を振らず、そのまま最終イベントへ進む。
3. 11枚目以外では d66 をロールする。
4. 「次のd66」に対する修正・固定・振り直し等があれば適用し、d66 の最終結果を確定する。
5. 6～10枚目では、確定後の d66 結果がその枚数の最終イベント出現条件に該当するか判定する。該当した場合は通常マップイベントを処理せず最終イベントへ進む。
6. 最終イベントが出現しなかった場合は、確定後の d66 結果に対応する通常のマップイベントを解決する。
"""
new_steps = """1. 次の区域へ進出する。
2. 11枚目なら d66 を振らず、そのまま最終イベントへ進む。
3. 11枚目以外では d66 をロールする。
4. 「次のd66」に対する修正・固定・振り直し等があれば適用し、d66 の最終結果を確定する。
5. 6～10枚目では、確定後の d66 結果がその枚数の最終イベント出現条件に該当するか判定する。この判定では、その番号が解決済みかどうかは確認しない。該当した場合は通常マップイベントを処理せず最終イベントへ進む。
6. 最終イベントが出現しなかった場合に限り、確定後の d66 番号が解決済みか確認する。解決済みなら05章の手順に従い、未使用番号へ到達するまで番号を繰り上げる。この繰り上げ後の番号では最終イベント出現判定をやり直さない。
7. 最後に確定した未使用番号に対応する通常のマップイベントを解決する。
"""
if s.count(old_steps) != 1:
    raise SystemExit(f"step marker count must be 1, got {s.count(old_steps)}")
s = s.replace(old_steps, new_steps, 1)
scenario.write_text(s, encoding="utf-8")

audit = Path("docs/SCENARIO_V1_01_RESOURCE_BALANCE_AUDIT.md")
a = audit.read_text(encoding="utf-8")
heading = "## 31. Black Sun 解決済みd66番号と最終イベント判定の順序 — 採用済み"
section = """

## 31. Black Sun 解決済みd66番号と最終イベント判定の順序 — 採用済み

ユーザー承認により、一本道モードでは、補正後に確定したd66結果による最終イベント出現判定を、解決済み番号の未使用番号への繰り上げより先に行う。

- 6～10枚目では、まず補正後のd66結果そのものを使って最終イベント出現判定を行う。
- この時点では、そのd66番号が過去に解決済みかどうかを考慮しない。
- 最終イベントが出現した場合は、通常マップ番号の解決済み確認や繰り上げを行わず、そのまま最終イベントへ進む。
- 最終イベントが出現しなかった場合に限り、確定後のd66番号が解決済みか確認する。
- 解決済みなら05章どおり、未使用番号へ到達するまで番号を順に繰り上げる。
- 繰り上げ後の番号を使って最終イベント出現判定をやり直さない。
- 5枚目は最終イベントが出現しないため、補正後のd66番号から通常どおり解決済み確認・繰り上げを行う。

これにより、過去に低い番号のイベントを多く解決したことによって、6～10枚目の最終イベント出現率が意図せず低下することを防ぐ。
"""
if heading not in a:
    audit.write_text(a.rstrip() + section + "\n", encoding="utf-8")
